// lz-compress: greedy LZ77 over a generated byte buffer (see lz-compress.mi).

package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"
)

func generatedInput(n int) []byte {
	data := make([]byte, 0, n)
	state := int64(11)
	for len(data) < n {
		state = state * 48271 % 2147483647
		if len(data) > 64 && state%4 == 0 {
			back := 1 + int((state/4)%60)
			length := 3 + (state/256)%20
			for k := int64(0); k < length && len(data) < n; k++ {
				data = append(data, data[len(data)-back])
			}
		} else {
			data = append(data, byte(97+state%16))
		}
	}
	return data
}

func kernel(n int64) string {
	data := generatedInput(int(n))
	size := len(data)
	var literals, matches, hash int64
	pos := 0
	for pos < size {
		bestLength, bestDistance := 0, 0
		start := 0
		if pos > 255 {
			start = pos - 255
		}
		for ; start < pos; start++ {
			length := 0
			for pos+length < size && length < 255 && data[start+length] == data[pos+length] {
				length++
			}
			if length > bestLength {
				bestLength = length
				bestDistance = pos - start
			}
		}
		if bestLength >= 3 {
			matches++
			hash = (hash*31 + int64(bestDistance*256+bestLength)) % 1000000007
			pos += bestLength
		} else {
			literals++
			hash = (hash*31 + int64(data[pos])) % 1000000007
			pos++
		}
	}
	return fmt.Sprintf("%d %d %d", literals, matches, hash)
}

func runHot(input int64) string {
	expected := kernel(input)
	agree := true
	for i := 1; i < 5; i++ {
		checksum := kernel(input)
		agree = agree && checksum == expected
	}
	for i := 0; i < 5; i++ {
		start := time.Now()
		checksum := kernel(input)
		elapsed := time.Since(start).Nanoseconds()
		fmt.Fprintf(os.Stderr, "hot_ns=%d\n", elapsed)
		agree = agree && checksum == expected
	}
	if !agree {
		fmt.Fprintln(os.Stderr, "checksum differs between iterations")
		os.Exit(1)
	}
	return expected
}

func main() {
	text, err := os.ReadFile(os.Args[1])
	if err != nil {
		os.Exit(2)
	}
	n, err := strconv.ParseInt(strings.TrimSpace(string(text)), 10, 64)
	if err != nil {
		os.Exit(2)
	}
	if len(os.Args) > 2 && os.Args[2] == "hot" {
		fmt.Println(runHot(n))
	} else {
		fmt.Println(kernel(n))
	}
}
